30: * daemon reads stdin so answers and EOF are handled while the host waits for an activity.
31: * The initial ready event precedes all responses; setChecked is silent at the port and
32: * therefore emits no fabricated change events. IO failure ends the session; malformed
33: * requests produce error frames and leave the session usable.
34: * Business requests require a matching hello; ready alone grants no business access.
35: */
36:@Slf4j
37:final class IpcServer {
38:    private final Uiport port;
39:    private final IpcSession session;
40:    private final BackendIdentity identity;
41:    private boolean welcomed;
42:    private WorkspaceVm pageSnapshot;
43:    private java.util.List<ItemVm> pageItems;
44:    private final ArrayDeque<String> deferred = new ArrayDeque<>();
45:    private boolean disconnected;
46:    private final ObjectMapper json = new ObjectMapper()
47:            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
48:            .enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
49:
50:    IpcServer(Uiport port) throws IOException {
51:        this.port = Objects.requireNonNull(port, "port");
52:        this.session = null;
53:        this.identity = BackendIdentity.current();
54:    }
55:
56:    IpcServer(IpcSession session) throws IOException {
57:        this.port = session.port;
58:        this.session = session;
59:        this.identity = BackendIdentity.current();
60:    }
61:
62:    void run(InputStream input, OutputStream output) throws IOException {
63:        welcomed = false;
64:        // Borrowed stdio: the caller owns stream lifetime. Never use PrintWriter (swallows IO errors).
65:        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(output, StandardCharsets.UTF_8));
66:        ObjectNode ready = frame("event").put("event", "ready");
67:        ArrayNode methods = ready.putObject("data").putArray("methods").add("workspace").add("setChecked");
68:        if (session != null) {
69:            IpcSession.METHODS.forEach(methods::add);
70:            session.events(event -> {
71:                try { write(writer, event); }
72:                catch (IOException e) { throw new UncheckedIOException(e); }
73:            });
74:        }
75:        methods.add("hello");
76:        write(writer, ready);
77:        disconnected = false;
78:        deferred.clear();
79:        try (var incoming = new IpcInput(input)) {
80:            if (session != null) session.inputPump(() -> pump(incoming, writer));
81:            while (!disconnected) {
82:                String line;
83:                if (!deferred.isEmpty()) line = deferred.removeFirst();
84:                else {
85:                    var received = incoming.take();
86:                    if (received.line() == null) {
87:                        endInput(received);
88:                        break;
89:                    }
90:                    line = received.line();
91:                }
92:                write(writer, dispatch(line));
93:            }
94:        } catch (UncheckedIOException e) {
95:            throw e.getCause();
96:        } catch (InterruptedException e) {
97:            Thread.currentThread().interrupt();
98:            throw new IOException("IPC host interrupted", e);
99:        } finally {
100:            if (session != null) {
101:                session.inputPump(() -> { });
102:                session.events(event -> { }); // Failed output must not prevent cancellation or cleanup.
103:                session.disconnect();
104:            }
105:        }
106:    }
107:
108:    private void endInput(IpcInput.Received received) throws IOException {
109:        disconnected = true;
110:        if (received.failure() != null) throw received.failure();
111:        if (session != null) session.disconnect();
112:    }
113:
114:    private void pump(IpcInput incoming, BufferedWriter writer) {
115:        if (disconnected) return;
116:        try {
117:            // EOF is not delayed behind a backlog of ordinary requests while a confirmation is pending.
118:            if (incoming.end() != null) { endInput(incoming.end()); return; }
119:            var received = incoming.poll();
120:            if (received == null) return;
121:            if (received.line() == null) { endInput(received); return; }
122:            JsonNode request;
123:            try { request = json.readTree(received.line()); }
124:            catch (JsonProcessingException e) { write(writer, dispatch(received.line())); return; }
125:            if (request != null && request.path("method").asText().equals("confirmAnswer")) {
126:                write(writer, dispatch(received.line()));
127:            } else if (deferred.size() < 256) {
128:                deferred.addLast(received.line()); // No other command may mutate an active model snapshot.
129:            } else {
130:                String id = request != null && request.path("id").isTextual() ? request.path("id").asText() : null;
131:                write(writer, error(id, "INVALID_REQUEST", "Too many queued requests during activity"));
132:            }
133:        } catch (IOException e) {
134:            throw new UncheckedIOException(e);
135:        }
136:    }
137:
138:    private ObjectNode dispatch(String line) {
139:        JsonNode request;
140:        try {
141:            request = json.readTree(line);
142:        } catch (JsonProcessingException e) {
143:            return error(null, "BAD_JSON", "Expected one JSON object per line");
144:        }
145:        String id = request != null && request.path("id").isTextual()
146:                && !request.path("id").asText().isEmpty() ? request.path("id").asText() : null;
147:        if (request == null || !request.isObject() || id == null
148:                || !request.path("v").isIntegralNumber() || !request.path("v").canConvertToInt()
149:                || request.path("v").intValue() != 1
150:                || !request.path("type").asText().equals("request")
151:                || !request.path("method").isTextual() || !request.path("params").isObject()) {
152:            return error(id, "INVALID_REQUEST", "Expected v=1, type=request, nonempty string id, method and object params");
153:        }
154:        JsonNode params = request.path("params");
155:        if (request.path("method").asText().equals("hello")) return hello(id, params);
156:        if (!welcomed) return error(id, "HANDSHAKE_FAILED", "Send matching hello before business requests");
157:        try {
158:            JsonNode result;
159:            switch (request.path("method").asText()) {
160:                case "workspace" -> result = workspace(port.queries().workspace());
161:                case "setChecked" -> {
162:                    if (!params.path("paths").isArray() || !params.path("checked").isBoolean()) {
163:                        return error(id, "INVALID_PARAMS", "setChecked requires paths array and boolean checked");
164:                    }
165:                    // Validate the entire array before invoking a mutating command.
166:                    var paths = new ArrayList<String>();
167:                    for (JsonNode path : params.path("paths")) {
168:                        if (!path.isTextual() && !path.isNull()) {
169:                            return error(id, "INVALID_PARAMS", "paths entries must be strings or null");
170:                        }
171:                        paths.add(path.isNull() ? null : path.textValue());
172:                    }
173:                    port.commands().setChecked(paths, params.path("checked").booleanValue());
174:                    pageSnapshot = null;
175:                    result = json.nullNode();
176:                }
177:                default -> {
178:                    String method = request.path("method").asText();
179:                    if (session == null || !IpcSession.METHODS.contains(method)) {
180:                        return error(id, "UNKNOWN_METHOD", "Unknown method: " + method);
181:                    }
182:                    if (method.equals("workspacePage")) result = page(params);
183:                    else {
184:                        result = session.call(method, params);
185:                        pageSnapshot = null;
186:                    }
187:                }
188:            }
189:            ObjectNode response = frame("response").put("id", id);
190:            response.set("result", result);
191:            return response;
192:        } catch (UncheckedIOException e) {
193:            throw e;
194:        } catch (IllegalArgumentException | JsonProcessingException | java.nio.file.NoSuchFileException e) {
195:            return error(id, "INVALID_PARAMS", "Invalid method parameters");
196:        } catch (Exception e) {
197:            log.error("IPC request failed: id={}", id, e);
198:            return error(id, "INTERNAL_ERROR", "Request failed; see backend log");
199:        }
200:    }
201:
202:    private ObjectNode hello(String id, JsonNode params) {
203:        // A failed repeat handshake revokes the previous agreement as well.
204:        welcomed = false;
205:        if (!params.path("protocolVersion").isIntegralNumber()
206:                || !params.path("protocolVersion").canConvertToInt()
207:                || params.path("protocolVersion").intValue() < 1
208:                || !params.path("version").isTextual() || params.path("version").asText().isBlank()
209:                || !params.path("buildId").isTextual() || params.path("buildId").asText().isBlank()) {
210:            return error(id, "INVALID_PARAMS", "hello requires positive integer protocolVersion and nonempty version/buildId");
211:        }
212:        BackendIdentity expected = new BackendIdentity(params.path("protocolVersion").intValue(),
213:                params.path("version").asText(), params.path("buildId").asText());
214:        String mismatch = expected.mismatch(identity);
215:        if (mismatch != null) return error(id, "HANDSHAKE_FAILED", mismatch);
216:        ObjectNode response = frame("response").put("id", id);
217:        ObjectNode welcome = response.putObject("result").put("kind", "welcome")
218:                .put("protocolVersion", identity.protocolVersion()).put("version", identity.version())
219:                .put("buildId", identity.buildId());
220:        ArrayNode capabilities = welcome.putArray("capabilities").add("workspace").add("setChecked");
221:        if (session != null) capabilities.add("workspacePage").add("bulkFiles").add("confirmationRoundTrip");
222:        welcome.put("confirmationRoundTrip", session != null);
223:        welcomed = true;
224:        return response;
225:    }
226:
227:    private ObjectNode page(JsonNode params) {
228:        for (String key : java.util.List.of("offset", "limit")) {
229:            if (!params.path(key).isIntegralNumber() || !params.path(key).canConvertToInt()) {
230:                throw new IllegalArgumentException("Integer page bounds required");
231:            }
232:        }
233:        int offset = params.path("offset").intValue();
234:        int limit = params.path("limit").intValue();
235:        if (offset < 0 || limit < 1 || limit > 256) throw new IllegalArgumentException("Page bounds out of range");
236:        if (pageSnapshot == null) {
237:            pageSnapshot = port.queries().workspace();
238:            var flat = new ArrayList<ItemVm>(pageSnapshot.topLevelItems());
239:            pageSnapshot.groups().forEach(group -> flat.addAll(group.members()));
240:            pageItems = java.util.List.copyOf(flat);
241:        }
242:        ObjectNode result = json.createObjectNode().put("total", pageItems.size()).put("offset", offset)
243:                .put("groupCount", pageSnapshot.groups().size());
244:        ArrayNode entries = result.putArray("items");
245:        int end = (int) Math.min(pageItems.size(), (long) offset + limit);
246:        for (int i = offset; i < end; i++) entries.add(item(pageItems.get(i)));
247:        return result;
248:    }
249:
250:    // Explicit wire mapping avoids reflective DTO registration for a future native backend.
251:    // Tests compare this mapping against Jackson's independent serialization of the port records.
252:    private ObjectNode workspace(WorkspaceVm vm) {
253:        ObjectNode result = json.createObjectNode();
254:        ArrayNode groups = result.putArray("groups");
255:        for (GroupVm group : vm.groups()) {
256:            ObjectNode entry = groups.addObject().put("no", group.no()).put("name", group.name())
257:                    .put("expanded", group.expanded()).put("defaultNamed", group.defaultNamed());
258:            ArrayNode members = entry.putArray("members");
259:            group.members().forEach(item -> members.add(item(item)));
260:        }
261:        ArrayNode items = result.putArray("topLevelItems");
262:        vm.topLevelItems().forEach(item -> items.add(item(item)));
263:        return result.put("canUndo", vm.canUndo()).put("undoDepth", vm.undoDepth())
264:                .put("selection", vm.selection().name());
265:    }
266:
267:    private ObjectNode item(ItemVm vm) {
268:        return json.createObjectNode().put("id", vm.id()).put("name", vm.name())
269:                .put("checked", vm.checked()).put("removed", vm.removed())
270:                .put("unitIndex", vm.unitIndex()).put("update", vm.update().name());
271:    }
272:
273:    private ObjectNode frame(String type) {
274:        return json.createObjectNode().put("v", 1).put("type", type);
275:    }
276:
277:    private ObjectNode error(String id, String code, String message) {
278:        ObjectNode frame = frame("error").put("id", id);
279:        frame.putObject("error").put("code", code).put("message", message);
280:        return frame;
281:    }
282:
283:    private void write(BufferedWriter writer, ObjectNode frame) throws IOException {
284:        writer.write(json.writeValueAsString(frame));
285:        writer.write('\n');
286:        writer.flush();
287:    }
288:}

