130:                String id = request != null && request.path("id").isTextual() ? request.path("id").asText() : null;
131:                write(writer, error(id, "INVALID_REQUEST", "Too many queued requests during activity"));
132:            }
133:        } catch (IOException e) {
134:            throw new UncheckedIOException(e);
135:        }
136:    }
137:
138:    private ObjectNode dispatch(String line) {
139:        JsonNode request;
140:        try {
141:            request = json.readTree(line);
142:        } catch (JsonProcessingException e) {
143:            return error(null, "BAD_JSON", "Expected one JSON object per line");
144:        }
145:        String id = request != null && request.path("id").isTextual()
146:                && !request.path("id").asText().isEmpty() ? request.path("id").asText() : null;
147:        if (request == null || !request.isObject() || id == null
148:                || !request.path("v").isIntegralNumber() || !request.path("v").canConvertToInt()
149:                || request.path("v").intValue() != 1
150:                || !request.path("type").asText().equals("request")
151:                || !request.path("method").isTextual() || !request.path("params").isObject()) {
152:            return error(id, "INVALID_REQUEST", "Expected v=1, type=request, nonempty string id, method and object params");
153:        }
154:        JsonNode params = request.path("params");
155:        if (request.path("method").asText().equals("hello")) return hello(id, params);
156:        if (!welcomed) return error(id, "HANDSHAKE_FAILED", "Send matching hello before business requests");
157:        try {
158:            JsonNode result;
159:            switch (request.path("method").asText()) {
160:                case "workspace" -> result = workspace(port.queries().workspace());
161:                case "setChecked" -> {
162:                    if (!params.path("paths").isArray() || !params.path("checked").isBoolean()) {
163:                        return error(id, "INVALID_PARAMS", "setChecked requires paths array and boolean checked");
164:                    }
165:                    // Validate the entire array before invoking a mutating command.
166:                    var paths = new ArrayList<String>();
167:                    for (JsonNode path : params.path("paths")) {
168:                        if (!path.isTextual() && !path.isNull()) {
169:                            return error(id, "INVALID_PARAMS", "paths entries must be strings or null");
170:                        }
171:                        paths.add(path.isNull() ? null : path.textValue());
172:                    }
173:                    port.commands().setChecked(paths, params.path("checked").booleanValue());
174:                    pageSnapshot = null;
175:                    result = json.nullNode();
176:                }
177:                default -> {
178:                    String method = request.path("method").asText();
179:                    if (session == null || !IpcSession.METHODS.contains(method)) {
180:                        return error(id, "UNKNOWN_METHOD", "Unknown method: " + method);
181:                    }
182:                    if (method.equals("workspacePage")) result = page(params);
183:                    else {
184:                        result = session.call(method, params);
185:                        pageSnapshot = null;
186:                    }
187:                }
188:            }
189:            ObjectNode response = frame("response").put("id", id);
190:            response.set("result", result);
191:            return response;
192:        } catch (UncheckedIOException e) {
193:            throw e;
194:        } catch (IllegalArgumentException | JsonProcessingException | java.nio.file.NoSuchFileException e) {
195:            return error(id, "INVALID_PARAMS", "Invalid method parameters");
196:        } catch (Exception e) {
197:            log.error("IPC request failed: id={}", id, e);
198:            return error(id, "INTERNAL_ERROR", "Request failed; see backend log");
199:        }
200:    }
201:
202:    private ObjectNode hello(String id, JsonNode params) {
203:        // A failed repeat handshake revokes the previous agreement as well.
204:        welcomed = false;
205:        if (!params.path("protocolVersion").isIntegralNumber()
206:                || !params.path("protocolVersion").canConvertToInt()
207:                || params.path("protocolVersion").intValue() < 1
208:                || !params.path("version").isTextual() || params.path("version").asText().isBlank()
209:                || !params.path("buildId").isTextual() || params.path("buildId").asText().isBlank()) {
210:            return error(id, "INVALID_PARAMS", "hello requires positive integer protocolVersion and nonempty version/buildId");
211:        }
212:        BackendIdentity expected = new BackendIdentity(params.path("protocolVersion").intValue(),
213:                params.path("version").asText(), params.path("buildId").asText());
214:        String mismatch = expected.mismatch(identity);
215:        if (mismatch != null) return error(id, "HANDSHAKE_FAILED", mismatch);
216:        ObjectNode response = frame("response").put("id", id);
217:        ObjectNode welcome = response.putObject("result").put("kind", "welcome")
218:                .put("protocolVersion", identity.protocolVersion()).put("version", identity.version())
219:                .put("buildId", identity.buildId());
220:        ArrayNode capabilities = welcome.putArray("capabilities").add("workspace").add("setChecked");
221:        if (session != null) capabilities.add("workspacePage").add("bulkFiles").add("confirmationRoundTrip");
222:        welcome.put("confirmationRoundTrip", session != null);
223:        welcomed = true;
224:        return response;
225:    }
226:
227:    private ObjectNode page(JsonNode params) {
228:        for (String key : java.util.List.of("offset", "limit")) {
229:            if (!params.path(key).isIntegralNumber() || !params.path(key).canConvertToInt()) {
230:                throw new IllegalArgumentException("Integer page bounds required");
231:            }
232:        }
233:        int offset = params.path("offset").intValue();
234:        int limit = params.path("limit").intValue();
235:        if (offset < 0 || limit < 1 || limit > 256) throw new IllegalArgumentException("Page bounds out of range");
236:        if (pageSnapshot == null) {
237:            pageSnapshot = port.queries().workspace();
238:            var flat = new ArrayList<ItemVm>(pageSnapshot.topLevelItems());
239:            pageSnapshot.groups().forEach(group -> flat.addAll(group.members()));
240:            pageItems = java.util.List.copyOf(flat);
241:        }
242:        ObjectNode result = json.createObjectNode().put("total", pageItems.size()).put("offset", offset)
243:                .put("groupCount", pageSnapshot.groups().size());
244:        ArrayNode entries = result.putArray("items");
245:        int end = (int) Math.min(pageItems.size(), (long) offset + limit);
246:        for (int i = offset; i < end; i++) entries.add(item(pageItems.get(i)));
247:        return result;
248:    }
249:
250:    // Explicit wire mapping avoids reflective DTO registration for a future native backend.
251:    // Tests compare this mapping against Jackson's independent serialization of the port records.
252:    private ObjectNode workspace(WorkspaceVm vm) {
253:        ObjectNode result = json.createObjectNode();
254:        ArrayNode groups = result.putArray("groups");
255:        for (GroupVm group : vm.groups()) {
256:            ObjectNode entry = groups.addObject().put("no", group.no()).put("name", group.name())
257:                    .put("expanded", group.expanded()).put("defaultNamed", group.defaultNamed());
258:            ArrayNode members = entry.putArray("members");
259:            group.members().forEach(item -> members.add(item(item)));
260:        }
261:        ArrayNode items = result.putArray("topLevelItems");
262:        vm.topLevelItems().forEach(item -> items.add(item(item)));
263:        return result.put("canUndo", vm.canUndo()).put("undoDepth", vm.undoDepth())
264:                .put("selection", vm.selection().name());
265:    }
266:
267:    private ObjectNode item(ItemVm vm) {
268:        return json.createObjectNode().put("id", vm.id()).put("name", vm.name())
269:                .put("checked", vm.checked()).put("removed", vm.removed())
270:                .put("unitIndex", vm.unitIndex()).put("update", vm.update().name());
271:    }
272:
273:    private ObjectNode frame(String type) {
274:        return json.createObjectNode().put("v", 1).put("type", type);
275:    }
276:
277:    private ObjectNode error(String id, String code, String message) {
278:        ObjectNode frame = frame("error").put("id", id);
279:        frame.putObject("error").put("code", code).put("message", message);
280:        return frame;
281:    }
282:
283:    private void write(BufferedWriter writer, ObjectNode frame) throws IOException {
284:        writer.write(json.writeValueAsString(frame));
285:        writer.write('\n');
286:        writer.flush();
287:    }
288:}

1:package com.mhtextractor.backend;
2:
3:import com.fasterxml.jackson.databind.JsonNode;
4:import com.fasterxml.jackson.databind.ObjectMapper;
5:import com.fasterxml.jackson.databind.node.ObjectNode;
6:import com.mhtextractor.app.*;
7:import com.mhtextractor.core.SourceParsers;
8:import com.mhtextractor.model.AppConfig;
9:import com.mhtextractor.model.ParamScope;
10:import com.mhtextractor.model.PreviewItem;
11:import com.mhtextractor.model.ThumbnailData;
12:import com.mhtextractor.uiport.*;
13:
14:import java.io.IOException;
15:import java.lang.management.ManagementFactory;
16:import java.nio.charset.StandardCharsets;
17:import java.nio.file.Files;
18:import java.nio.file.Path;
19:import java.util.List;
20:import java.util.concurrent.ArrayBlockingQueue;
21:import java.util.concurrent.TimeUnit;
22:import java.util.function.Consumer;
23:
24:/** Backend host assembly. All model commands and callbacks run on the serial IPC host thread. */
25:final class IpcSession implements AutoCloseable {
26:    static final List<String> METHODS = List.of("importPaths", "group", "setParams", "extract",
27:            "workspacePage", "previewFiles", "fileInfo", "releaseFiles", "metrics", "confirmAnswer");
28:    private final ObjectMapper json;
29:    private final WorkspaceModel model = new WorkspaceModel();
30:    private final GlobalParameterCache global = new GlobalParameterCache();
31:    private final ArrayBlockingQueue<Runnable> callbacks = new ArrayBlockingQueue<>(256);
32:    private final Thread host = Thread.currentThread();
33:    private final IpcFiles files;
34:    private final PreviewSession previews;
35:    private final PreviewService previewService;
36:    private final WorkspaceExtractionCoordinator extractions;
37:    private final IpcConfirmations confirmations;
38:    final Uiport port;
39:    private Consumer<ObjectNode> events;
40:    private boolean importDone;
41:    private boolean importFailed;
42:    private PortEvent.ExtractionTerminal terminal;
43:    private boolean imageMode;
44:    private String outputFolder;
45:    private int progressBucket = -1;
46:    private long rawProgress;
47:    private long sentProgress;
48:    private volatile int queuePeak;
49:    private volatile boolean closing;
50:    private volatile boolean disconnecting;
51:    private Runnable inputPump = () -> { };
52:
53:    IpcSession(ObjectMapper json) throws IOException {
54:        this.json = json;
55:        confirmations = new IpcConfirmations(json, this::dispatch, data -> emit("confirmationRequested", data),
56:                data -> emit("confirmationExpired", data));
57:        files = new IpcFiles(json);
58:        previews = PreviewSession.create(files.root.resolve("preview-cache"));
59:        previewService = new PreviewService(previews.lifecycle());
60:        var plans = new ExtractionPlanService(new ExtractionPlanService.Context() {
61:            public List<Object> dataOrder() { return model.topLevel(); }
62:            public boolean imageMode() { return imageMode; }
63:            public AppConfig textParamsCache() { return global.text(); }
64:            public AppConfig imageParamsCache() { return global.image(); }
65:            public String inputFolder() { return null; }
66:            public String outputFolder() { return outputFolder; }
67:            public boolean openFolderAfterComplete() { return false; }
68:        });
69:        Confirmer confirmer = confirmations;
70:        var activities = new WorkspaceActivityService(new WorkspaceActivityService.Context() {
71:            public List<PreviewItem> items() { return model.allItems(); }
72:            public boolean textMode() { return !imageMode; }
73:            public AppConfig effectiveParams(PreviewItem item) { return params(item, imageMode); }
74:            public AppConfig effectiveImageParams(PreviewItem item) { return params(item, true); }
75:        }, previewService, (image, index, config) -> new ThumbnailData("", 0, 0, null), this::dispatch);
76:        var clipboard = new ParamClipboard(model::push, target -> ParamScope.GLOBAL, (target, mode, config) -> { });
77:        var paramCommands = new WorkspaceParamCommandService(model, new WorkspaceParamService(previews.lifecycle()),
78:                global, clipboard::pushParamUndo);
79:        // A server import round is bounded to 20k inputs; continuing requires a client decision.
80:        var imports = new WorkspaceImportCoordinator(model, confirmer, this::dispatch, 200, 20000);
81:        extractions = new WorkspaceExtractionCoordinator(new WorkspaceExtractionService(previews.lifecycle()),
82:                WorkspaceExtractionCoordinator.productionRequests(plans,
83:                        () -> model.allItems().stream().filter(item -> !item.removed).toList(), confirmer), this::dispatch);
84:        port = new InProcessUiport(model, confirmer, plans, activities, paramCommands, imports, extractions);
85:        port.events().subscribe(this::onEvent);
86:    }
87:
88:    void events(Consumer<ObjectNode> sink) { events = sink; }
89:
90:    void inputPump(Runnable pump) { inputPump = pump; }
91:
92:    void disconnect() {
93:        if (disconnecting) return;
94:        disconnecting = true;
95:        try {
96:            // Mark the run cancelled before waking its confirmation waiter; otherwise it may win a natural-completion race.
97:            port.commands().cancelExtraction();
98:        } finally {
99:            confirmations.disconnect(); // Also release import confirmations, even if terminal delivery broke stdout.
100:            port.commands().cancelWorkspaceActivity();
101:        }
102:    }
103:
104:    private AppConfig params(PreviewItem item, boolean mode) {
105:        AppConfig config = ParamScope.effectiveParams(item.parentGroup, item.textItemParams,
106:                item.imageItemParams, mode, global.text(), global.image());
107:        return config == null ? new AppConfig() : config;
108:    }
109:
110:    private void dispatch(Runnable callback) {
111:        if (closing) return;
112:        if (Thread.currentThread() == host) { callback.run(); return; }
113:        try {
114:            while (!closing && !callbacks.offer(callback, 100, TimeUnit.MILLISECONDS)) { }
115:            queuePeak = Math.max(queuePeak, callbacks.size());
116:        } catch (InterruptedException e) {
117:            Thread.currentThread().interrupt();
118:            if (closing || disconnecting) return; // Expected shutdown interrupt must not escape the worker's final dispatch.
119:            throw new IllegalStateException("Host dispatch interrupted", e);
120:        }
121:    }
122:
123:    private void await(java.util.function.BooleanSupplier done) throws InterruptedException {
124:        // Synchronous methods finish their activity before responding; no worker touches the model afterward.
125:        while (!done.getAsBoolean()) {
126:            inputPump.run();
127:            Runnable callback = callbacks.poll(25, TimeUnit.MILLISECONDS);
128:            if (callback != null) callback.run();
129:        }
130:    }
131:
132:    private void emit(String name, ObjectNode data) {
133:        ObjectNode frame = json.createObjectNode().put("v", 1).put("type", "event").put("event", name);
134:        frame.set("data", data);
135:        events.accept(frame);
136:    }
137:
138:    private void onEvent(PortEvent event) {
139:        switch (event) {
140:            case PortEvent.ImportRound round -> emit("importRound", json.createObjectNode()
141:                    .put("generation", round.generation()).put("newFiles", round.newFiles()).put("newGroups", round.newGroups()));
142:            case PortEvent.ImportFinished finished -> {
143:                importDone = true;
144:                emit("importFinished", json.createObjectNode().put("generation", finished.generation())
145:                        .put("count", finished.accumulatedPaths().size()).put("failed", importFailed));
146:            }
147:            case PortEvent.Notice notice -> {
148:                importFailed = true;
149:                emit("notice", json.createObjectNode().put("key", notice.key()));
150:            }
151:            case PortEvent.ParamStateChanged changed -> emit("paramsChanged", json.createObjectNode()
152:                    .put("kind", changed.kind().name()).put("affectedCount", changed.affectedPaths().size()));
153:            case PortEvent.ExtractionProgress progress -> {
154:                rawProgress++;
155:                int bucket = (int) (Math.clamp(progress.overall(), 0, 1) * 100);
156:                if (bucket > progressBucket) {
157:                    progressBucket = bucket;
158:                    sentProgress++;
159:                    emit("extractionProgress", json.createObjectNode().put("generation", progress.generation())
160:                            .put("overall", progress.overall()));
161:                }
162:            }
163:            case PortEvent.ExtractionTerminal end -> {
164:                terminal = end;
165:                emit("extractionTerminal", terminalSummary(end));
166:            }
167:            default -> { } // No automatic workspace snapshots, per-item payloads, or thumbnail pixels.
168:        }
169:    }
170:
171:    private ObjectNode terminalSummary(PortEvent.ExtractionTerminal end) {
172:        ObjectNode summary = json.createObjectNode().put("generation", end.generation()).put("end", end.end().name())
173:                .put("outputFolder", end.sessionOutputFolder());
174:        if (end.stats() != null) summary.put("count", end.stats().files().size()).put("failCount", end.stats().failCount())
175:                .put("skipCount", end.stats().skipCount()).put("warnCount", end.stats().warnCount());
176:        return summary;
177:    }
178:
179:    JsonNode call(String method, JsonNode p) throws Exception {
180:        switch (method) {
181:            case "confirmAnswer" -> {
182:                String id = string(p, "confirmationId");
183:                JsonNode action = p.get("actionKey");
184:                if (action == null || (!action.isNull() && !action.isTextual())) {
185:                    throw new IllegalArgumentException("actionKey string or null required");
186:                }
187:                return json.createObjectNode().put("accepted", confirmations.answer(id, action.isNull() ? null : action.asText()));
188:            }
189:            case "importPaths" -> {
190:                List<String> paths = strings(p, "paths");
191:                for (String path : paths) IpcFiles.input(path);
192:                importDone = false;
193:                importFailed = false;
194:                port.commands().importPaths(paths, "IPC", false);
195:                await(() -> importDone);
196:                return json.createObjectNode().put("count", model.allItems().size()).put("failed", importFailed);
197:            }
198:            case "group" -> {
199:                List<String> paths = strings(p, "paths");
200:                String prefix = string(p, "namePrefix");
201:                port.commands().group(paths, prefix);
202:                return json.nullNode();
203:            }
204:            case "setParams" -> {
205:                boolean mode = bool(p, "imageMode");
206:                if (!p.path("config").isObject()) throw new IllegalArgumentException("config object required");
207:                AppConfig config = json.treeToValue(p.path("config"), AppConfig.class);
208:                port.commands().setGlobalParams(mode, config);
209:                imageMode = mode;
210:                return json.nullNode();
211:            }
212:            case "extract" -> {
213:                boolean checked = bool(p, "checkedOnly");
214:                String out = string(p, "outputFolder");
215:                if (model.allItems().stream().noneMatch(item -> !item.removed && (!checked || item.selected))) {
216:                    throw new IllegalArgumentException("No extraction targets");
217:                }
218:                // Revalidate imported ids immediately before the parser opens them.
219:                for (PreviewItem item : model.allItems()) if (!item.removed) IpcFiles.input(item.path);
220:                outputFolder = IpcFiles.output(out).toString();
221:                terminal = null;
222:                progressBucket = -1;
223:                port.commands().startExtraction(checked);
224:                await(() -> terminal != null);
225:                var result = terminalSummary(terminal);
226:                if (terminal.stats() != null) {
227:                    var outcomes = json.createArrayNode();
228:                    for (var outcome : terminal.stats().files()) outcomes.addObject().put("path", outcome.path())
229:                            .put("outcome", outcome.outcome().name()).put("message", outcome.message());
230:                    result.set("resultsFile", files.write(".json", json.writeValueAsBytes(outcomes), "application/json"));
231:                }
232:                // Use the lifecycle's batch deletion for completed inputs (same deletion semantics as rule b).
233:                previews.lifecycle().onItemsRemoved(model.allItems().stream().map(item -> item.path).toList());
234:                return result;
235:            }
236:            case "previewFiles" -> { return preview(p); }
237:            case "fileInfo" -> {
238:                Path path = files.validateIssued(string(p, "path"));
239:                return files.issue(path, "application/octet-stream");
240:            }
241:            case "releaseFiles" -> {
242:                List<String> paths = strings(p, "paths");
243:                for (String path : paths) files.validateIssued(path); // Atomic validation before deletion.
244:                for (String path : paths.stream().distinct().toList()) files.release(path);
245:                return json.nullNode();
246:            }
247:            case "metrics" -> {
248:                long peak = ManagementFactory.getMemoryPoolMXBeans().stream()
249:                        .filter(pool -> pool.getType() == java.lang.management.MemoryType.HEAP)
250:                        .mapToLong(pool -> Math.max(0, pool.getPeakUsage().getUsed())).sum();
251:                return json.createObjectNode().put("heapPoolPeakBytes", peak).put("callbackQueuePeak", queuePeak)
252:                        .put("rawProgress", rawProgress).put("sentProgress", sentProgress);
253:            }
254:            default -> throw new IllegalArgumentException("Unknown extension method");
255:        }
256:    }
257:
258:    private ObjectNode preview(JsonNode p) throws Exception {
259:        String id = string(p, "path");
260:        PreviewItem item = model.allItems().stream().filter(it -> it.path.equals(id) && !it.removed).findFirst()
261:                .orElseThrow(() -> new IllegalArgumentException("Preview requires an imported item id"));
262:        Path source = IpcFiles.input(id);
263:        var text = SourceParseService.parse(id, params(item, false), true);
264:        var parsed = SourceParsers.forPath(id).parse(id, true, () -> false, null, null);
265:        var result = previewService.ensureCachedLocked(previewService.prepare(source, params(item, true)), () -> false);
266:        ObjectNode manifest = json.createObjectNode();
267:        manifest.set("text", files.write(".txt", (text.text() == null ? "" : text.text()).getBytes(StandardCharsets.UTF_8), "text/plain; charset=utf-8"));
268:        manifest.set("html", files.write(".html", (parsed.getHtmlContent() == null ? "" : parsed.getHtmlContent())
269:                .getBytes(StandardCharsets.UTF_8), "text/html; charset=utf-8"));
270:        var thumbs = manifest.putArray("thumbnails");
271:        for (int i = 0; i < result.images().size(); i++) {
272:            Path image = previews.store().imageFileFor(result.meta(), i);
273:            ObjectNode ref = files.issue(image, "image/" + result.meta().images().get(i).detectedExt());
274:            ref.put("name", result.thumbs().get(i).coreName()).put("index", i);
275:            thumbs.add(ref); // Encoded original: client decodes/scales, never ARGB/base64 over stdio.
276:        }
277:        return json.createObjectNode().put("imageCount", thumbs.size())
278:                .set("manifest", files.write(".json", json.writeValueAsBytes(manifest), "application/json"));
279:    }
280:
281:    static String string(JsonNode p, String key) {
282:        if (!p.path(key).isTextual() || p.path(key).asText().isBlank()) throw new IllegalArgumentException(key + " string required");
283:        return p.path(key).asText();
284:    }
285:
286:    static boolean bool(JsonNode p, String key) {
287:        if (!p.path(key).isBoolean()) throw new IllegalArgumentException(key + " boolean required");
288:        return p.path(key).booleanValue();
289:    }
290:
291:    static List<String> strings(JsonNode p, String key) {
292:        if (!p.path(key).isArray() || p.path(key).isEmpty()) throw new IllegalArgumentException(key + " nonempty array required");
293:        var paths = new java.util.ArrayList<String>();
294:        for (JsonNode value : p.path(key)) {
295:            if (!value.isTextual() || value.asText().isBlank()) throw new IllegalArgumentException(key + " string entries required");
296:            paths.add(value.asText());
297:        }
298:        return paths;
299:    }
300:
301:    @Override public void close() throws IOException {
302:        closing = true;
303:        events = event -> { };
304:        callbacks.clear();
305:        disconnect();
306:        try {
307:            var channel = extractions.channel();
308:            if (channel != null) channel.result.get(10, TimeUnit.SECONDS);
309:        } catch (Exception e) {
310:            throw new IOException("Extraction worker did not finish during shutdown", e);
311:        } finally {
312:            previews.lifecycle().onShutdown(() -> { });
313:            files.close();
314:        }
315:    }
316:}

