367:    // ==================== 视图模型快照（只读、每次重新组装、不缓存） ====================
368:
369:    private WorkspaceVm snapshot() {
370:        // 显示序中每个可见条目的 0 基序号（R10：顶层条目按显示序里排在它前面的可见条目计数，
371:        // 含展开组成员 —— 与 GUI 的 unitIndex 同一口径）
372:        Map<PreviewItem, Integer> displayIndex = new IdentityHashMap<>();
373:        int itemCount = 0;
374:        for (Object o : model.displayOrder()) {
375:            if (o instanceof PreviewItem it) {
376:                displayIndex.put(it, itemCount++);
377:            }
378:        }
379:
380:        List<GroupVm> groups = new ArrayList<>();
381:        List<ItemVm> topLevelItems = new ArrayList<>();
382:        for (Object o : model.topLevel()) {
383:            if (o instanceof GroupItem<?> raw) {
384:                groups.add(toGroupVm(GroupStructure.asPreviewGroup(raw)));
385:            } else if (o instanceof PreviewItem it) {
386:                topLevelItems.add(toItemVm(it, displayIndex.get(it)));
387:            }
388:        }
389:        return new WorkspaceVm(groups, topLevelItems, model.canUndo(), model.undoDepth(), selection());
390:    }
391:
392:    private static GroupVm toGroupVm(GroupItem<PreviewItem> g) {
393:        List<ItemVm> members = new ArrayList<>();
394:        int visibleIndex = 0;
395:        for (PreviewItem m : g.getMembers()) {
396:            members.add(toItemVm(m, m.removed ? null : visibleIndex++));
397:        }
398:        return new GroupVm(g.getGroupNo(), g.getName(), g.isExpanded(), g.isDefaultNamed(), members);
399:    }
400:
401:    private static ItemVm toItemVm(PreviewItem it, Integer unitIndex) {
402:        return new ItemVm(it.path, it.name, it.selected, it.removed, unitIndex, UpdateKind.NONE);
403:    }
404:
405:    /** 勾选三态：候选 = 全部可见条目（顶层 + 组内，removed 除外）；口径见 {@link TriState}。 */
406:    private TriState selection() {
407:        List<PreviewItem> candidates = model.allItems().stream().filter(i -> !i.removed).toList();
408:        long selected = candidates.stream().filter(i -> i.selected).count();
409:        if (candidates.isEmpty() || selected == 0) {
410:            return TriState.NONE;
411:        }
412:        return selected == candidates.size() ? TriState.ALL : TriState.SOME;
413:    }
414:
415:    /** 按路径解析条目（保持入参顺序；未知路径静默跳过）。路径是导入去重后的唯一键。 */
416:    private List<PreviewItem> resolveItems(List<String> paths) {
417:        if (paths == null || paths.isEmpty()) {
418:            return List.of();
419:        }
420:        Map<String, PreviewItem> byPath = new HashMap<>();
421:        for (PreviewItem it : model.allItems()) {
422:            byPath.putIfAbsent(it.path, it);
423:        }
424:        List<PreviewItem> out = new ArrayList<>();
425:        for (String p : paths) {
426:            PreviewItem it = p == null ? null : byPath.get(p);
427:            if (it != null) {
428:                out.add(it);
429:            }
430:        }
431:        return out;
432:    }
433:}

