44:    @Override public ConfirmToken confirm(ConfirmRequest request) {
45:        Pending token;
46:        synchronized (this) {
47:            long limit = request.timeoutMs() > 0 ? Math.min(request.timeoutMs(), timeoutMs) : timeoutMs;
48:            token = new Pending(sessionId + "-" + ++sequence, request, limit);
49:            if (disconnected) token.answer.complete(null);
50:            else pending.put(token.id, token);
51:        }
52:        dispatch.accept(() -> {
53:            synchronized (this) {
54:                if (!pending.containsKey(token.id)) return;
55:            }
56:            ObjectNode data = json.createObjectNode().put("confirmationId", token.id).put("key", request.key())
57:                    .putNull("defaultAction").put("timeoutMs", token.limit);
58:            ObjectNode params = data.putObject("namedParams");
59:            request.namedParams().forEach(params::put);
60:            var actions = data.putArray("actionKeys");
61:            request.actionKeys().forEach(actions::add);
62:            // message() is deliberately never serialized: clients render keys and named parameters.
63:            events.accept(data);
64:        });
65:        return token;
66:    }
