68:    synchronized boolean answer(String id, String action) {
69:        Pending token = pending.get(id);
70:        if (token == null) return false; // Expired / duplicate / old-session answers cannot affect another card.
71:        if (action != null && !token.request.actionKeys().contains(action)) {
72:            throw new IllegalArgumentException("Answer must be an offered action or null");
73:        }
74:        if (System.nanoTime() - token.started >= TimeUnit.MILLISECONDS.toNanos(token.limit)) {
75:            expire(token);
76:            return false;
77:        }
78:        return complete(token, action);
79:    }
80:
81:    private synchronized boolean complete(Pending token, String action) {
82:        if (!pending.remove(token.id, token)) return false;
83:        return token.answer.complete(action);
84:    }
85:
86:    private void expire(Pending token) {
87:        synchronized (this) {
88:            if (!pending.remove(token.id, token)) return;
89:        }
90:        // Queue expiry before releasing the worker, so it precedes any next card / activity terminal.
91:        try {
92:            dispatch.accept(() -> expirations.accept(json.createObjectNode().put("confirmationId", token.id)));
93:        } finally {
94:            token.answer.complete(null); // A broken expiry notification must still release its waiter.
95:        }
96:    }
97:
98:    synchronized void disconnect() {
99:        disconnected = true;
100:        pending.values().forEach(token -> token.answer.complete(null));
101:        pending.clear();
102:    }
