104:    private final class Pending implements ConfirmToken {
105:        final String id;
106:        final ConfirmRequest request;
107:        final long limit;
108:        final long started = System.nanoTime();
109:        final CompletableFuture<String> answer = new CompletableFuture<>();
110:
111:        Pending(String id, ConfirmRequest request, long limit) {
112:            this.id = id;
113:            this.request = request;
114:            this.limit = limit;
115:        }
116:
117:        @Override public void answer(String actionKey) { IpcConfirmations.this.answer(id, actionKey); }
118:        @Override public void cancel() { complete(this, null); }
119:
120:        @Override public String await() throws InterruptedException {
121:            try {
122:                long remaining = TimeUnit.MILLISECONDS.toNanos(limit) - (System.nanoTime() - started);
123:                return answer.get(Math.max(0, remaining), TimeUnit.NANOSECONDS);
124:            } catch (TimeoutException e) {
125:                expire(this);
126:                return answer.join(); // An answer that won the race remains the sole delivered decision.
127:            } catch (java.util.concurrent.ExecutionException e) {
128:                throw new IllegalStateException(e.getCause());
129:            } catch (InterruptedException e) {
130:                cancel();
131:                throw e;
132:            }
133:        }
134:    }
